import promptTemplate from '../prompt-template/2024-prompt-template.md';
import { OpenAI } from "openai"

function getResult (openaiClient, inputPrompt) {
  const completion = openaiClient.createChatCompletion({
    model: "gpt-4-1106-preview",
    messages: [
      {
        role: 'system',
        content: promptTemplate,
      },
      {
        role: "user",
        content: inputPrompt,
      },
    ],
    max_tokens: 7500,
    n: 1,
    temperature: 1,
  });
  return completion;
}


